def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = [float(v) for v in history if math.isfinite(float(v))]
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    p = 24 if 'hour' in frequency.lower() else (7 if 'day' in frequency.lower() else 1)

    def make(train, h, kind):
        if not train:
            return [0.0] * h
        level = statistics.median(train[-min(len(train), p):])
        if kind == 'last':
            return [train[-1]] * h
        if kind == 'level':
            return [level] * h
        cycles = int(kind.split('_')[-1]) if kind.startswith('season_') else 4
        pattern = []
        for phase in range(p):
            vals = []
            for c in range(cycles):
                idx = len(train) - p + phase - c * p
                if idx >= 0:
                    vals.append(train[idx])
            pattern.append(statistics.median(vals) if vals else level)
        if kind == 'shrink':
            pattern = [0.65 * v + 0.35 * level for v in pattern]
        return [float(pattern[k % p]) for k in range(h)]

    def smape(actual, pred):
        terms = []
        for a, b in zip(actual, pred):
            den = abs(a) + abs(b)
            terms.append(0.0 if den < 1e-12 else 200.0 * abs(a - b) / den)
        return sum(terms) / len(terms) if terms else float('inf')

    kinds = ['last', 'level', 'season_2', 'season_4', 'season_6', 'shrink']
    folds = min(5, max(0, len(x) // p - 2))
    if folds == 0:
        return make(x, horizon, 'level')
    scores = {k: [] for k in kinds}
    for j in range(folds, 0, -1):
        origin = len(x) - j * p
        train = x[:origin]
        actual = x[origin:min(origin + p, len(x))]
        if len(train) < p or not actual:
            continue
        for kind in kinds:
            scores[kind].append(smape(actual, make(train, len(actual), kind)))
    objectives = {}
    for kind, vals in scores.items():
        if not vals:
            objectives[kind] = float('inf')
            continue
        center = statistics.median(vals)
        mad = statistics.median([abs(v - center) for v in vals])
        objectives[kind] = center + 0.25 * mad
    chosen = min(kinds, key=lambda k: objectives[k])
    return make(x, horizon, chosen)

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = [float(v) for v in history if math.isfinite(float(v))]
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    p = 24 if 'hour' in frequency.lower() else (7 if 'day' in frequency.lower() else 1)

    def quantile(vals, q):
        vals = sorted(vals)
        if not vals:
            return 0.0
        pos = q * (len(vals) - 1)
        lo = int(math.floor(pos))
        hi = int(math.ceil(pos))
        if lo == hi:
            return vals[lo]
        return vals[lo] * (hi - pos) + vals[hi] * (pos - lo)

    def make(train, h, q, shrink):
        recent = train[-min(len(train), p):]
        level = statistics.median(recent)
        pattern = []
        cycles = min(7, len(train) // p)
        for phase in range(p):
            vals = []
            for c in range(cycles):
                idx = len(train) - p + phase - c * p
                if idx >= 0:
                    vals.append(train[idx])
            phase_value = quantile(vals, q) if vals else level
            pattern.append((1.0 - shrink) * phase_value + shrink * level)
        return [float(pattern[k % p]) for k in range(h)]

    def smape(actual, pred):
        total = 0.0
        for a, b in zip(actual, pred):
            den = abs(a) + abs(b)
            total += 0.0 if den < 1e-12 else 200.0 * abs(a - b) / den
        return total / len(actual) if actual else float('inf')

    settings = [(q, s) for q in (0.25, 0.35, 0.5, 0.65) for s in (0.0, 0.25, 0.5)]
    folds = min(5, max(0, len(x) // p - 2))
    if folds < 2:
        return make(x, horizon, 0.5, 0.25)
    results = {}
    for setting in settings:
        vals = []
        for j in range(folds, 0, -1):
            origin = len(x) - j * p
            train = x[:origin]
            actual = x[origin:min(origin + p, len(x))]
            if len(train) >= 2 * p and actual:
                vals.append(smape(actual, make(train, len(actual), setting[0], setting[1])))
        center = statistics.median(vals) if vals else float('inf')
        spread = statistics.median([abs(v - center) for v in vals]) if vals else float('inf')
        results[setting] = center + 0.2 * spread
    chosen = min(settings, key=lambda z: results[z])
    return make(x, horizon, chosen[0], chosen[1])
